# browser-harness < tests/architecture-archetypes.browser.py
assert page_info()['url'].startswith(('http://localhost:', 'http://127.0.0.1:')), 'Open the local preview first'
result=js(r'''(async()=>{
 const T=await import('three'),r=await import('./js/world/city-rollout.js'),{stops}=await import('./js/content.js'),{routePoints,routeCurve}=await import('./js/world/layout.js'),{buildCity}=await import('./js/world/city.js');
 const check=(ok,msg)=>{if(!ok)throw Error(msg)},pts=routePoints(stops.length),plots=[];buildCity(()=>{},stops,pts,routeCurve(T,pts),undefined,undefined,p=>plots.push(p));
 const before=JSON.stringify(plots),regions=new Set(),observed=new Set(),samples={};
 for(const kind of ['townhouse','shop','midrise','office','tower'])samples[kind]=plots.find(p=>r.classifyPlot(p)===kind);
 check(Object.values(samples).every(Boolean),'missing a representative building family');
 for(const p of plots){const kind=r.classifyPlot(p);if(!kind)continue;const recipe=r.rolloutRecipe(p,kind,plots);check(recipe.archetype&&recipe.region,'missing deterministic facade archetype/region for '+p.id);observed.add(recipe.archetype);regions.add(recipe.region);check(JSON.stringify(recipe)===JSON.stringify(r.rolloutRecipe(p,kind,plots)),'non-deterministic recipe '+p.id);}
 const existing=[['brick-terrace','townhouse'],['side-gable-terrace','townhouse'],['hip-roof-terrace','townhouse'],['high-street-shop','shop'],['wraparound-shop','shop'],['stone-tenement','midrise'],['banded-apartment','midrise'],['horizontal-office','office'],['vertical-office','office'],['straight-tower','tower'],['stepped-tower','tower'],['asymmetric-tower','tower']],regional=[['paulista-arcade-shop','shop'],['paulista-brise-apartment','midrise'],['paulista-finned-tower','tower'],['london-bay-terrace','townhouse'],['london-mansion-block','midrise'],['london-corner-pub','shop'],['glasgow-blonde-bay-tenement','midrise'],['glasgow-red-stepped-tenement','midrise'],['glasgow-sandstone-gabled-row','townhouse'],['country-slate-cottage','townhouse'],['country-garden-pair','townhouse'],['country-garden-flat','midrise']],catalog=[...existing,...regional];
 check(catalog.length===24&&new Set(catalog.map(([name])=>name)).size===24,'expected a 24-name archetype catalog');
 const geometrySignature=(kind,q)=>JSON.stringify(kind==='townhouse'?[q.roof,q.bays,q.bands,q.bayWindows??false,q.entryGable??false,q.chimney??false,q.gardenPair??false]:kind==='shop'?[q.composition,q.storeBays,q.roofCap??null,q.arcade??false,q.cornerPub??false]:kind==='midrise'?[q.emphasis,q.penthouse,q.rooftop,q.brise??false,q.bayWindows??false,q.mansion??false,q.steppedRoof??false,q.gardenRoof??false]:kind==='office'?[q.emphasis,q.crown,q.rooftop]:[q.silhouette,q.crown,q.finDepth??.10,q.finWidth??.13]);
 const groups={townhouse:new Map(),shop:new Map(),midrise:new Map(),office:new Map(),tower:new Map()};
 for(const [name,kind] of catalog){const p={...samples[kind],archetype:name},recipe=r.rolloutRecipe(p,kind,plots),repeat=r.rolloutRecipe(p,kind,plots.slice().reverse());check(recipe.archetype===name&&recipe.region,'explicit archetype did not resolve: '+name);check(JSON.stringify(recipe)===JSON.stringify(repeat),'non-deterministic explicit recipe '+name);groups[kind].set(name,geometrySignature(kind,recipe));}
 const expected={townhouse:7,shop:4,midrise:7,office:2,tower:4};for(const [kind,count] of Object.entries(expected)){check(groups[kind].size===count,kind+' does not expose '+count+' explicit archetypes');check(new Set(groups[kind].values()).size===count,kind+' labels archetypes without distinct geometry profiles');}
 check(new Set(catalog.map(([name])=>name)).size===24&&[...observed].every(name=>catalog.some(([known])=>known===name))&&catalog.every(([name])=>observed.has(name)),'all 24 styles must appear in the live regional city');check(observed.has('country-slate-cottage')&&observed.has('country-garden-pair'),'country descriptors do not expose both new townhouse archetypes');check(regions.size>=4,'expected Paulista, London, countryside and Glasgow regional palettes');check(JSON.stringify(plots)===before,'archetype selection mutated source lot descriptors');
 return {pass:true,catalogCount:catalog.length,archetypes:Object.fromEntries(Object.entries(groups).map(([kind,values])=>[kind,[...values.keys()].sort()])),regions:[...regions].sort()};
})()''')
print(result)
assert isinstance(result,dict) and result.get('pass'),result
